                        }
                    },
                    ctrlc.clone(),
                )?
                .filter(
                    move |value| {
                        finder_filter.value_should_be_printed(
                            value,
                            &filter_config,
                            &lower_terms,
                            span,
                            &cols_to_search_in_filter,
                            invert,
                        )
                    },
                    ctrlc,
                )
        }
        PipelineData::ListStream(stream, metadata) => {
            let stream = stream.modify(|iter| {
                let map_finder = finder.clone();
                let filter_finder = finder.clone();
                let cols_to_search_in_map = cols_to_search_in_map.clone();
                let cols_to_search_in_filter = cols_to_search_in_filter.clone();
                let terms = terms.clone();
                let config = config.clone();
                let filter_config = filter_config.clone();
                let lower_terms = lower_terms.clone();
                iter.map(move |mut x| {
                    let span = x.span();
                    match &mut x {
                        Value::Record { val, .. } => map_finder
                            .highlight_terms_in_record_with_search_columns(
                                &cols_to_search_in_map,
                                val,
                                span,
                                &config,
                                &terms,
                                string_style,
                                highlight_style,
                            ),
                        _ => x,
                    }
                })
                .filter(move |value| {
                    filter_finder.value_should_be_printed(
                        value,
                        &filter_config,
                        &lower_terms,
                        span,
                        &cols_to_search_in_filter,
                        invert,
                    )
                })
            });

            Ok(PipelineData::ListStream(stream, metadata))
        }
        PipelineData::ByteStream(stream, ..) => {
            let span = stream.span();
            if let Some(lines) = stream.lines() {
                let terms = lower_terms
                    .into_iter()
                    .map(|term| finder.fold_text(&term.to_expanded_string("", &filter_config)))
                    .collect::<Vec<_>>();

                let mut output: Vec<Value> = vec![];
